        let comparisons = &result.comparisons;
        result
            .ordinals
            .values_mut()
            .sort_unstable_by(|left, right| {
                #[cfg(test)]
                comparisons.set(comparisons.get() + 1);
                parameters[*left].name.cmp(&parameters[*right].name)
            });
        Ok(result)
